(function(){
'use strict';
var C=window.LEED_CONFIG, BANK=[], active=[], session=null, timer=null, paletteMode='all', result=null, reviewMode='all', reviewDomain='all', collapsed=false;
var CATEGORY_ORDER=['LEED Overview & Process','Integrative Process','Location & Transportation','Sustainable Sites','Water Efficiency','Energy & Atmosphere','Materials & Resources','Indoor Environmental Quality','Innovation & Regional Priority'];
function el(id){return document.getElementById(id)}
function escapeHtml(v){return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function pad(n){return n<10?'0'+n:n} function timeText(s){return pad(Math.floor(s/3600))+':'+pad(Math.floor((s%3600)/60))+':'+pad(s%60)}
function screen(name){el('menu').className=name==='menu'?'panel':'panel hidden';el('exam').className=name==='exam'?'panel':'panel hidden';el('results').className=name==='results'?'panel':'panel hidden'}
function progressKey(t,m){return C.storagePrefix+'progress_'+m+'_'+t} function historyKey(){return C.storagePrefix+'history'} function usedKey(){return C.storagePrefix+'used_mix'}
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch(e){return fallback}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));if(window.LEED_SYNC)window.LEED_SYNC.scheduleUpload()}catch(e){}}
function validateData(){var i,j,q,fields=['q','options','answer','category','purpose','vocabulary','keywords','logic','purpose_vi','vocabulary_vi','keywords_vi','logic_vi'],k;for(i=1;i<=C.testCount;i++){BANK[i-1]=window['LEED_TEST_'+i];if(!BANK[i-1]||BANK[i-1].length<100)throw new Error('Test '+i+' không đủ 100 câu.');for(j=0;j<BANK[i-1].length;j++){q=BANK[i-1][j];if(!q.options||q.options.length!==4||typeof q.answer!=='number'||q.answer<0||q.answer>3)throw new Error('Đáp án lỗi tại Test '+i+', câu '+(j+1));for(k=0;k<fields.length;k++)if(q[fields[k]]===undefined||q[fields[k]]===null)throw new Error('Thiếu '+fields[k]+' tại Test '+i+', câu '+(j+1));}}}
function shuffle(a){var i,j,t;for(i=a.length-1;i>0;i--){j=Math.floor(Math.random()*(i+1));t=a[i];a[i]=a[j];a[j]=t}return a}
function answerOrder(mix){var a=[0,1,2,3];if(!mix)return a;shuffle(a);if(a.join(',')==='0,1,2,3')a=[1,0,3,2];return a}
function fixedMap(test,mix){var a=[],i;for(i=0;i<BANK[test].length;i++)a.push([test,i]);if(mix)shuffle(a);return a.slice(0,100)}
function mixStemKey(q){return String(q.q||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/^ +| +$/g,'')}function bankMap(){var pool=[],used=read(usedKey(),[]),available=[],seen={},i,j,id,key,out=[];for(i=0;i<BANK.length;i++)for(j=0;j<BANK[i].length;j++){key=mixStemKey(BANK[i][j]);if(seen[key])continue;seen[key]=true;id=BANK[i][j].id||i+'-'+j;pool.push({id:id,key:key,map:[i,j]})}for(i=0;i<pool.length;i++)if(used.indexOf(pool[i].id)<0)available.push(pool[i]);if(available.length<100){used=[];available=pool.slice(0)}shuffle(available);seen={};for(i=0;i<available.length&&out.length<100;i++){if(seen[available[i].key])continue;seen[available[i].key]=true;out.push(available[i].map);used.push(available[i].id)}if(out.length<100)throw new Error('Không đủ 100 câu duy nhất cho Auto Mix.');write(usedKey(),used);return out}
function newSession(test,mode,strategy){var i,s={test:test,mode:mode,strategy:strategy,index:0,answers:[],flags:[],checked:[],remaining:C.examSeconds,startedAt:(new Date()).getTime(),submitted:false,autoAdvance:mode==='exam',map:null,orders:[]};s.map=test===-1?bankMap():fixedMap(test,mode==='exam');for(i=0;i<100;i++){s.answers[i]=null;s.flags[i]=false;s.checked[i]=false;s.orders[i]=answerOrder(mode==='exam'||test===-1)}return s}
function buildActive(){var i,source,order,x,k;active=[];for(i=0;i<100;i++){source=BANK[session.map[i][0]][session.map[i][1]];order=session.orders[i]||[0,1,2,3];x={};for(k in source)if(source.hasOwnProperty(k))x[k]=source[k];x.options=[];x.options_vi=[];x.wrong_reasons_vi=[];x.wrong_reasons_en=[];for(k=0;k<4;k++){x.options[k]=source.options[order[k]];if(source.options_vi&&source.options_vi.length===4)x.options_vi[k]=source.options_vi[order[k]];if(source.wrong_reasons_vi&&source.wrong_reasons_vi.length===4)x.wrong_reasons_vi[k]=source.wrong_reasons_vi[order[k]];if(source.wrong_reasons_en&&source.wrong_reasons_en.length===4)x.wrong_reasons_en[k]=source.wrong_reasons_en[order[k]]}for(k=0;k<4;k++)if(order[k]===source.answer)x.answer=k;active.push(x)}}
function saveProgress(){if(session&&!session.submitted){session.updatedAt=(new Date()).getTime();write(progressKey(session.test,session.mode),session)}}
function bind(){el('exit-btn').onclick=goMenu;el('result-menu-btn').onclick=goMenu;el('prev-btn').onclick=function(){move(-1)};el('next-btn').onclick=function(){move(1)};el('flag-btn').onclick=toggleFlag;el('check-btn').onclick=checkPractice;el('submit-btn').onclick=confirmSubmit;el('auto-advance').onchange=function(){session.autoAdvance=this.checked;saveProgress()};el('all-btn').onclick=function(){paletteMode='all';renderPalette()};el('unanswered-btn').onclick=function(){paletteMode='unanswered';renderPalette()};el('next-empty-btn').onclick=nextEmpty;el('review-all').onclick=function(){setReview('all')};el('review-correct').onclick=function(){setReview('correct')};el('review-wrong').onclick=function(){setReview('wrong')};el('review-blank').onclick=function(){setReview('blank')};el('review-flagged').onclick=function(){setReview('flagged')};el('review-domain').onchange=function(){reviewDomain=this.value;renderReview()};el('collapse-all').onclick=toggleCollapse;el('history-test-filter').onchange=renderHistory;el('history-mode-filter').onchange=renderHistory;el('history-collapse-all-btn').onclick=toggleAllHistoryGroups;el('history-select-all').onchange=toggleSelectAllHistory;el('delete-selected-history-btn').onclick=deleteSelectedHistory;el('clear-history-btn').onclick=clearHistory}
function testNote(i){var n=i+1;if(n<=6)return '600 câu nguồn · 100 câu/Test';if(n===7)return 'LEED v5 BD+C · GA-level';if(n===8)return 'LEED v5 ID+C · GA-level';if(n===9)return 'LEED v5 O+M · GA-level';return 'LEED v5 BD+C / ID+C / O+M · Mixed Mock'}function renderMenu(){var h='',i;screen('menu');if(timer){clearInterval(timer);timer=null}for(i=0;i<C.testCount;i++){h+='<div class="test-card exam-card" onclick="LEED_APP.start('+i+',\'exam\',false)"><div class="mode-card-label exam-label">EXAM MODE</div><h3>Test '+(i+1)+' · Thi thử</h3><p class="small"><strong>'+testNote(i)+'</strong><br>100 câu · 120 phút · xáo thứ tự câu và đáp án ở mỗi phiên mới.</p><button type="button" class="btn primary mode-start-btn">Bắt đầu Exam Auto Mix</button></div>';h+='<div class="test-card practice-card" onclick="LEED_APP.start('+i+',\'practice\',false)"><div class="mode-card-label practice-label">PRACTICE MODE</div><h3>Test '+(i+1)+' · Luyện tập</h3><p class="small"><strong>'+testNote(i)+'</strong><br>Giữ thứ tự gốc · Check đáp án từng câu · có Submit và thống kê đầy đủ.</p><button type="button" class="btn practice-button mode-start-btn">Bắt đầu Practice</button></div>'}h+='<div class="test-card auto-mix-card" onclick="LEED_APP.start(-1,\'exam\',false)"><div class="mode-card-label exam-label">EXAM MODE</div><h3>Auto Mix toàn ngân hàng</h3><p>100 câu ngẫu nhiên từ 1.380 câu, xáo cả câu hỏi và đáp án.</p></div><div class="test-card auto-mix-card practice-card" onclick="LEED_APP.start(-1,\'practice\',false)"><div class="mode-card-label practice-label">PRACTICE MODE</div><h3>Auto Mix Practice</h3><p>100 câu ngẫu nhiên, Check từng câu và Submit thống kê.</p></div>';el('test-grid').innerHTML=h;renderResume();prepareHistoryFilter();renderSummary();renderHistory()}
function renderResume(){var h='',modes=['exam','practice'],t,m,s,n,i;for(m=0;m<2;m++)for(t=-1;t<C.testCount;t++){s=read(progressKey(t,modes[m]),null);if(s&&!s.submitted){n=0;for(i=0;i<100;i++)if(s.answers[i]!==null)n++;h+='<div class="resume-card"><b>'+(t===-1?'Auto Mix':'Test '+(t+1))+' · '+modes[m]+'</b> · '+n+'/100 <button class="btn success" onclick="LEED_APP.start('+t+',\''+modes[m]+'\',true)">Tiếp tục</button> <button class="btn danger" onclick="LEED_APP.discard('+t+',\''+modes[m]+'\')">Xóa</button></div>'}}el('resume').innerHTML=h}
function start(test,mode,resume){var saved=read(progressKey(test,mode),null);if(!resume&&saved&&!saved.submitted){if(confirm('Có bài làm dở. Tiếp tục?'))resume=true;else if(!confirm('Xóa bài cũ và tạo phiên mới?'))return}session=resume&&saved?saved:newSession(test,mode,test===-1?'bankMix':(mode==='exam'?'mix':'original'));if(!session.map||session.map.length!==100){session=newSession(test,mode,session.strategy)}buildActive();paletteMode='all';screen('exam');el('test-title').innerHTML=test===-1?'Auto Mix toàn ngân hàng':('Test '+(test+1)+' · '+(mode==='exam'?'Exam Auto Mix':'Practice gốc'));el('mode').innerHTML=mode==='exam'?'Exam Mode · câu và đáp án đã xáo':'Practice Mode · Unlimited';el('mode').style.background=mode==='exam'?'#4f46e5':'#9333ea';el('check-btn').className=mode==='practice'?'btn primary':'btn primary hidden';el('submit-btn').className='btn danger';el('submit-btn').innerHTML=mode==='exam'?'Nộp bài (Submit Exam)':'Submit Practice & xem thống kê';el('auto-advance-wrap').style.display=mode==='exam'?'block':'none';el('auto-advance').checked=!!session.autoAdvance;renderQuestion();if(mode==='exam')startTimer();else el('timer').innerHTML='Practice Mode · Unlimited'}
function startTimer(){if(timer)clearInterval(timer);el('timer').innerHTML=timeText(session.remaining);timer=setInterval(function(){session.remaining--;if(session.remaining<=0){session.remaining=0;saveProgress();clearInterval(timer);timer=null;submit();return}if(session.remaining%5===0)saveProgress();el('timer').innerHTML=timeText(session.remaining)},1000)}
function fitQuestionText(){var box=el('q-text'),size=18;if(!box)return;box.style.fontSize='';box.style.lineHeight='';box.style.overflow='hidden';size=parseFloat(window.getComputedStyle(box).fontSize)||18;while(size>10&&box.scrollHeight>box.clientHeight){size-=0.5;box.style.fontSize=size+'px';box.style.lineHeight='1.28'}if(box.scrollHeight>box.clientHeight){box.style.fontSize='10px';box.style.lineHeight='1.15'}}
function renderQuestion(){var q=active[session.index],h='',i,cl,locked=session.mode==='practice'&&session.checked[session.index];el('q-number').innerHTML='Question '+(session.index+1)+' of 100';el('q-category').innerHTML=escapeHtml(q.category);el('q-text').innerHTML=escapeHtml(q.q);fitQuestionText();for(i=0;i<4;i++){cl='option';if(session.answers[session.index]===i)cl+=' selected';if(locked){if(i===q.answer)cl+=' correct';else if(session.answers[session.index]===i)cl+=' wrong'}h+='<label class="'+cl+'"><input type="radio" name="answer" '+(session.answers[session.index]===i?'checked ':'')+(locked?'disabled ':'')+'onclick="LEED_APP.answer('+i+')"><span><b>'+String.fromCharCode(65+i)+'.</b> '+escapeHtml(q.options[i])+'</span></label>'}el('options').innerHTML=h;el('flag-btn').innerHTML=session.flags[session.index]?'Bỏ đánh dấu':'Đánh dấu';if(locked)renderExplanation(q);else el('explanation').style.display='none';renderPalette();saveProgress()}
function answer(i){if(session.mode==='practice'&&session.checked[session.index])return;session.answers[session.index]=i;renderQuestion();if(session.mode==='exam'&&session.autoAdvance&&session.index<99)setTimeout(function(){session.index++;renderQuestion()},250)}
function move(d){var n=session.index+d;if(n>=0&&n<100){session.index=n;renderQuestion()}} function jump(i){session.index=i;renderQuestion()} function toggleFlag(){session.flags[session.index]=!session.flags[session.index];renderQuestion()}
function checkPractice(){if(session.answers[session.index]===null){alert('Vui lòng chọn một đáp án.');return}session.checked[session.index]=true;renderQuestion()}
function coreEvidence(q){var x=String(q.evidence_en||q.explanation||'').replace(/\s+/g,' ').trim();return x.replace(/ This scenario tests.*$/,'').replace(/ This item applies.*$/,'').trim()}function translateOption(text){var exact={'A 100-year floodplain':'Vùng ngập lụt chu kỳ 100 năm','A parcel near existing utilities':'Khu đất gần hệ thống hạ tầng kỹ thuật hiện hữu','A site near a bus route':'Khu đất gần tuyến xe buýt','A compact mixed-use district':'Khu đô thị nén, đa chức năng','A previously developed urban parcel':'Khu đất đô thị đã được phát triển trước đây','An undisturbed wetland buffer':'Vùng đệm đất ngập nước chưa bị xáo trộn','Prime farmland':'Đất nông nghiệp có chất lượng cao','Habitat for an imperiled species':'Sinh cảnh của loài đang bị đe dọa','10 years':'10 năm','20 years':'20 năm','25 years':'25 năm','50 years':'50 năm','Solar photovoltaic panels':'Tấm quang điện mặt trời','On-site solar PV':'Điện mặt trời tại chỗ','Owner’s Project Requirements':'Yêu cầu dự án của chủ đầu tư','Owner Project Requirements':'Yêu cầu dự án của chủ đầu tư','Basis of Design':'Cơ sở thiết kế','Environmental Product Declaration':'Tuyên bố sản phẩm môi trường','Health Product Declaration':'Tuyên bố sản phẩm về sức khỏe','Native and adapted plants':'Thực vật bản địa và thích nghi','A vegetated roof':'Mái xanh có thảm thực vật','A green roof':'Mái xanh','Demand-controlled ventilation':'Thông gió điều khiển theo nhu cầu','Carbon dioxide sensors':'Cảm biến carbon dioxide','Low-flow plumbing fixtures':'Thiết bị vệ sinh lưu lượng thấp','Reclaimed water':'Nước tái chế','Rainwater harvesting':'Thu gom và sử dụng nước mưa'};if(exact[text])return exact[text];var x=text,repl=[[/^A parcel near /i,'Khu đất gần '],[/^A site near /i,'Khu đất gần '],[/^A building near /i,'Công trình gần '],[/^An? /i,'Một '],[/existing utilities/ig,'hạ tầng kỹ thuật hiện hữu'],[/bus route/ig,'tuyến xe buýt'],[/mixed-use district/ig,'khu đa chức năng'],[/wetland buffer/ig,'vùng đệm đất ngập nước'],[/floodplain/ig,'vùng ngập lụt'],[/prime farmland/ig,'đất nông nghiệp chất lượng cao'],[/habitat/ig,'sinh cảnh'],[/imperiled species/ig,'loài bị đe dọa'],[/previously developed/ig,'đã phát triển trước đây'],[/renewable energy/ig,'năng lượng tái tạo'],[/potable water/ig,'nước sạch'],[/outdoor air/ig,'không khí ngoài trời'],[/energy use/ig,'mức sử dụng năng lượng'],[/water use/ig,'mức sử dụng nước'],[/construction waste/ig,'chất thải xây dựng'],[/daylight/ig,'chiếu sáng tự nhiên'],[/thermal comfort/ig,'tiện nghi nhiệt'],[/low-emitting/ig,'phát thải thấp'],[/public transit/ig,'giao thông công cộng'],[/bicycle/ig,'xe đạp'],[/parking/ig,'bãi đỗ xe'],[/metering/ig,'đo đếm'],[/commissioning/ig,'commissioning'],[/refrigerant/ig,'môi chất lạnh'],[/embodied carbon/ig,'carbon hàm chứa'],[/operational carbon/ig,'carbon vận hành']];for(var i=0;i<repl.length;i++)x=x.replace(repl[i][0],repl[i][1]);return x===text?'Nghĩa tiếng Việt: '+text:x}function viFact(q){var t=(q.q+' '+q.options[q.answer]+' '+q.explanation).toLowerCase();if(/100-year floodplain|1% annual chance/.test(t))return'“Vùng ngập 100 năm” là vùng có 1% xác suất ngập trong bất kỳ năm nào. Sensitive Land Protection yêu cầu dấu chân phát triển trên khu đất chưa phát triển phải tránh vùng nguy cơ ngập này.';if(/25-year projection/.test(t))return'Carbon Assessment của LEED v5 cộng năng lượng vận hành, môi chất lạnh, carbon hàm chứa và dữ liệu giao thông tùy chọn trong kỳ dự báo 25 năm.';if(/previously developed/.test(t))return'Phát triển trên khu đất đã được sử dụng hoặc xây dựng trước đây giúp tận dụng hạ tầng sẵn có và tránh xáo trộn thêm đất tự nhiên nhạy cảm.';if(/cycles of concentration|blowdown/.test(t))return'Chu kỳ cô đặc cao hơn cho phép tái sử dụng nước nhiều lần hơn trước khi xả đáy, nên giảm nước bổ sung và lượng nước thải khi chất lượng nước cho phép.';if(/commissioning/.test(t))return'Commissioning xác minh các hệ thống được lắp đặt, thử nghiệm và vận hành phù hợp với Yêu cầu dự án của chủ đầu tư và Cơ sở thiết kế.';if(/solar pv|photovoltaic/.test(t))return'Điện mặt trời tạo điện từ nguồn tái tạo ngay tại dự án mà không cần đốt nhiên liệu hóa thạch trong vận hành thông thường.';if(/native|habitat|biodiversity/.test(t))return'Thực vật bản địa hoặc thích nghi hỗ trợ sinh cảnh, đa dạng sinh học và khả năng chống chịu, đồng thời hạn chế loài xâm lấn.';if(/rainwater|stormwater|hydrology/.test(t))return'Giữ, thấm hoặc tái sử dụng nước mưa làm giảm dòng chảy và giúp chu trình nước của khu đất gần với điều kiện tự nhiên hơn.';if(/ventilation|co2 sensor|outdoor air/.test(t))return'Thông gió và điều khiển theo nhu cầu cấp lượng không khí ngoài trời phù hợp với mật độ sử dụng, giúp duy trì IAQ mà không xử lý thừa không khí.';var x=String(q.why_correct_vi||q.logic_vi||q.explanation||'').replace(/\s+/g,' ').trim();return x}function bridge(q,vi){var a=q.options[q.answer],t=(q.q+' '+a+' '+q.explanation).toLowerCase();if(/100-year floodplain|1% annual chance/.test(t))return vi?'“Vùng ngập 100 năm” không có nghĩa là 100 năm mới ngập một lần. Đây là cách gọi vùng có xác suất ngập 1% trong mỗi năm. LEED yêu cầu tránh vùng có nguy cơ ngập từ 1%/năm trở lên khi phát triển khu đất chưa phát triển, nên 100-year floodplain là vị trí bị cấm. Ba phương án còn lại là đặc điểm vị trí thuận lợi cho phát triển và không phải loại đất nhạy cảm bị cấm trong câu hỏi.':'A 100-year floodplain does not mean flooding occurs only once every 100 years. It means a 1% chance of flooding in any given year. LEED requires undeveloped sites to avoid this flood-hazard area, so this location is prohibited.';if(/25-year projection/.test(t))return vi?'LEED v5 quy định cùng một kỳ dự báo 25 năm để cộng và so sánh carbon vận hành, môi chất lạnh, carbon hàm chứa và giao thông tùy chọn. Vì câu hỏi hỏi đúng thời hạn của công cụ, 25 năm là đáp án; các mốc khác không phải thời hạn do công cụ quy định.':'LEED v5 uses one 25-year projection to combine and compare the relevant carbon sources; therefore 25 years is the prescribed horizon.';if(/previously developed/.test(t))return vi?'Khu đất đã phát triển trước đây đã có tác động và thường có hạ tầng sẵn. Chọn vị trí này giúp tránh mở rộng dấu chân phát triển vào đất tự nhiên hoặc đất nhạy cảm mới.':'Previously developed land has already been disturbed and often has infrastructure, so using it avoids new disturbance of sensitive land.';if(/commissioning/.test(t))return vi?'Commissioning không chỉ là kiểm tra thiết bị riêng lẻ. Quá trình này xác nhận toàn bộ hệ thống được lắp đặt, thử nghiệm và vận hành đúng OPR và cơ sở thiết kế; đó là lý do đáp án mô tả việc xác minh hiệu suất hệ thống là đúng.':'Commissioning verifies that systems are installed, tested, and operated in accordance with the OPR and design basis.';if(/solar pv|photovoltaic/.test(t))return vi?'PV tạo điện tái tạo ngay tại dự án từ bức xạ mặt trời. Vì nguồn điện được tạo trong ranh giới dự án và không cần đốt nhiên liệu khi vận hành, đây là năng lượng tái tạo tại chỗ.':'PV produces renewable electricity within the project boundary without routine fuel combustion.';if(/cycles of concentration|blowdown/.test(t))return vi?'Chu kỳ cô đặc là số lần nước được tuần hoàn trước khi xả đáy. Chu kỳ cao hơn nghĩa là dùng lại nước nhiều hơn, nên cần ít nước bổ sung và tạo ít nước xả hơn, nếu chất lượng nước cho phép.':'Higher cycles reuse water more times before blowdown, reducing makeup and discharge water.';if(/purpose|objective|function/.test(q.q.toLowerCase()))return vi?'Đáp án đúng mô tả tác dụng chính mà yêu cầu LEED muốn đạt được. Những lựa chọn khác có thể là lợi ích liên quan, nhưng không phải mục tiêu trung tâm được hỏi.':'The correct answer states the primary function; the others are secondary or different outcomes.';if(/how many|what time|percentage|minimum|maximum|threshold/.test(q.q.toLowerCase()))return vi?'Câu hỏi yêu cầu một giá trị được LEED quy định. Đáp án đúng trùng với mốc nêu trong bằng chứng; các con số khác chỉ là phương án gây nhiễu.':'The correct option matches the prescribed LEED value; the other figures are distractors.';return vi?'Đáp án đúng tạo ra đúng tác động hoặc đáp ứng đúng yêu cầu được nêu trong bằng chứng. Mối liên hệ là trực tiếp, trong khi các lựa chọn khác chỉ gần nghĩa, tạo lợi ích phụ hoặc thuộc một yêu cầu khác.':'The correct option directly produces the required outcome; the others are related, secondary, or belong to another requirement.'}function qType(q){var t=q.q.toLowerCase();if(/how many|what time|percentage|minimum|maximum|threshold|points/.test(t))return'value';if(/purpose|objective|function|why/.test(t))return'purpose';if(/document|evidence|submission|report|record|platform/.test(t))return'document';if(/prohibited| not |except|least|would not/.test(' '+t))return'negative';if(/category|credit/.test(t))return'category';if(/strategy|measure|choice|site|location|source|system|approach|most directly|best/.test(t))return'strategy';return'concept'}function wrongSpecific(q,i,vi){var o=q.options[i],lc=o.toLowerCase(),t=qType(q);if(/transportation demand|single-occupancy|vehicle miles/.test((q.q+' '+q.explanation).toLowerCase())){if(/free parking/.test(lc))return vi?'Tăng đỗ xe miễn phí làm việc lái xe cá nhân hấp dẫn hơn, nên có thể tăng chuyến xe một người thay vì giảm VMT.':'Free parking encourages driving rather than reducing VMT.';if(/loading dock/.test(lc))return vi?'Kích thước khu bốc dỡ hàng liên quan logistics công trình, không thay đổi cách người sử dụng đi lại hằng ngày và không giảm chuyến xe một người.':'Loading dock size does not reduce commute trips or VMT.';if(/reflective paving/.test(lc))return vi?'Vật liệu lát phản xạ cao giúp giảm hiệu ứng đảo nhiệt, nhưng không tác động đến lựa chọn phương tiện hoặc số chuyến đi xe cá nhân.':'Reflective paving addresses heat island, not travel behavior or VMT.';}if(/existing utilities|bus route|mixed-use district/.test(lc)&&/floodplain|prohibited/.test((q.q+' '+q.explanation).toLowerCase()))return vi?'Đây là đặc điểm hỗ trợ phát triển nén hoặc tiếp cận hạ tầng/giao thông; không phải khu đất nhạy cảm bị Sensitive Land Protection cấm.':'This supports infrastructure access or compact development; it is not a prohibited sensitive land type.';if(/wetland|prime farmland|imperiled species/.test(lc))return vi?'Đây là loại đất hoặc sinh cảnh nhạy cảm cần bảo vệ; nếu câu hỏi hỏi vị trí thuận lợi để phát triển thì phương án này phải bị loại.':'This is sensitive land or habitat that should be protected, so it is unsuitable when the question asks for a favorable development site.';var pools={value:['Sai mốc/giá trị; bằng chứng LEED nêu một con số khác.','Con số này không phải ngưỡng chính thức của yêu cầu.','Đây là giá trị gây nhiễu, không khớp dữ kiện định lượng.'],purpose:['Chỉ mô tả lợi ích phụ, không phải mục tiêu chính.','Liên quan đến chủ đề nhưng không phải chức năng cốt lõi.','Mô tả một kết quả khác với điều câu hỏi yêu cầu.'],document:['Không phải hồ sơ hoặc công cụ dùng để chứng minh yêu cầu này.','Tài liệu này có chức năng khác.','Không cung cấp đúng dữ liệu mà LEED cần kiểm tra.'],negative:['Không đáp ứng từ khóa phủ định/ngoại lệ của câu hỏi.','Phương án này không thuộc đối tượng bị cấm hoặc bị loại.','Đi ngược điều kiện NOT/EXCEPT/prohibited.'],category:['Có liên quan nhưng thuộc credit/category khác.','Nhầm phạm vi ghi nhận chính của chiến lược.','Tác động chính không được tính trong category này.'],strategy:['Không tạo ra tác động trực tiếp mà câu hỏi yêu cầu.','Giải quyết vấn đề khác hoặc chỉ mang lại lợi ích phụ.','Thiếu cơ chế đáp ứng yêu cầu LEED đang được kiểm tra.'],concept:['Là khái niệm gần giống nhưng không đúng định nghĩa.','Chỉ đúng một phần và thiếu đặc điểm quyết định.','Không khớp bản chất của thuật ngữ được hỏi.']};var en={value:'Wrong value or threshold.',purpose:'A secondary benefit, not the primary purpose.',document:'Not the required evidence or tool.',negative:'Does not satisfy the negative or exception wording.',category:'Related, but belongs to another credit/category.',strategy:'Does not directly produce the requested outcome.',concept:'A related concept, but not the definition being tested.'};if(!vi)return en[t];var n=0;for(var k=0;k<q.id.length;k++)n+=q.id.charCodeAt(k);return pools[t][(n+i)%pools[t].length]}function optionCards(q,vi){var h='',i,tr;for(i=0;i<4;i++){if(i===q.answer)continue;tr=(q.options_vi&&q.options_vi[i])?q.options_vi[i]:translateOption(q.options[i]);h+='<div class="wrong-card"><div><b>'+String.fromCharCode(65+i)+'. '+escapeHtml(q.options[i])+'</b><small>'+(vi?'Dịch: ':'Vietnamese translation: ')+escapeHtml(tr)+'</small></div><span>'+escapeHtml(vi&&q.wrong_reasons_vi&&q.wrong_reasons_vi[i]?q.wrong_reasons_vi[i]:wrongSpecific(q,i,vi))+'</span></div>'}return h}function title5(q,vi){var t=qType(q),v=vi?{value:'Mốc LEED cần nhớ',purpose:'Bản chất của yêu cầu',document:'Bằng chứng cần nhận diện',negative:'Vì sao vị trí này bị cấm/loại',category:'Credit/category phù hợp',strategy:'Cơ chế làm cho giải pháp đúng',concept:'Khái niệm cốt lõi'}:{value:'Key LEED value',purpose:'Core purpose',document:'Required evidence',negative:'Why this option is prohibited/excluded',category:'Correct credit/category',strategy:'Why the strategy works',concept:'Core concept'};return v[t]}function viKind(q){var x=(q.q||'').toLowerCase();if(x.indexOf('except')>=0||x.indexOf(' not ')>=0)return'ngoai';if(x.indexOf('least appropriate')>=0)return'it';if(x.indexOf('first')>=0||x.indexOf('early')>=0||x.indexOf('next step')>=0)return'trinh';if(x.indexOf('minimum')>=0||x.indexOf('maximum')>=0||x.indexOf('at least')>=0||x.indexOf('%')>=0)return'nguong';if(x.indexOf('document')>=0||x.indexOf('evidence')>=0||x.indexOf('verify')>=0||x.indexOf('demonstrate')>=0)return'hoso';return'truc'}
function viPack(q){var k=viKind(q),m={ngoai:{v:'ngoại lệ: phương án không đáp ứng điều kiện chung; điều kiện chung: đặc điểm mà ba phương án còn lại cùng thỏa mãn; từ phủ định: dấu hiệu yêu cầu chọn phương án khác nhóm',kw:'Xác định điểm chung của ba phương án, sau đó chọn phương án không có điểm chung đó. Không chọn chỉ vì một phương án nghe kém tích cực.',core:'Câu hỏi yêu cầu tìm ngoại lệ. Đáp án đúng là phương án không tạo ra kết quả chung mà ba lựa chọn còn lại cùng tạo ra.'},it:{v:'ít phù hợp nhất: phương án đáp ứng yêu cầu ở mức thấp nhất; phạm vi áp dụng: đối tượng và điều kiện mà giải pháp có hiệu lực; mục tiêu chính: kết quả trực tiếp cần đạt',kw:'So sánh mức độ đáp ứng của từng phương án; chọn phương án bỏ sót điều kiện quan trọng nhất hoặc có liên hệ yếu nhất với mục tiêu.',core:'Đáp án đúng có mức độ phù hợp thấp nhất vì không đáp ứng đầy đủ mục tiêu, phạm vi hoặc điều kiện áp dụng của yêu cầu.'},trinh:{v:'bước đầu tiên: hành động phải thực hiện trước các bước khác; phối hợp sớm: trao đổi trước khi quyết định bị chốt; trình tự: thứ tự thực hiện để kết quả còn ảnh hưởng đến dự án',kw:'Chọn hành động phải diễn ra trước khi thiết kế, mua sắm hoặc vận hành bị chốt. Hành động đúng nhưng thực hiện muộn vẫn là phương án sai.',core:'Trọng tâm là trình tự. Đáp án đúng phải được thực hiện đủ sớm để kết quả còn có thể tác động đến các quyết định tiếp theo.'},nguong:{v:'ngưỡng: giá trị giới hạn phải đáp ứng; tối thiểu: không được thấp hơn giá trị nêu; tối đa: không được vượt quá giá trị nêu; đơn vị: cơ sở dùng để so sánh',kw:'Khoanh đại lượng, đơn vị và từ chỉ giới hạn; loại mọi phương án sai số, sai đơn vị hoặc vượt ra ngoài phạm vi được hỏi.',core:'Câu hỏi kiểm tra ngưỡng định lượng. Đáp án đúng phải khớp đồng thời đại lượng, đơn vị, giá trị giới hạn và điều kiện đi kèm.'},hoso:{v:'bằng chứng: tài liệu hoặc dữ liệu dùng để xác minh; hồ sơ chứng minh: tài liệu thể hiện việc đáp ứng yêu cầu; giải pháp kỹ thuật: hành động tạo ra kết quả',kw:'Xác định đề bài cần hồ sơ chứng minh hay giải pháp kỹ thuật. Báo cáo chỉ ghi nhận kết quả, không thay thế hành động tạo ra kết quả.',core:'Câu hỏi yêu cầu bằng chứng xác minh. Đáp án đúng là tài liệu hoặc dữ liệu chứng minh trực tiếp việc đáp ứng yêu cầu.'},truc:{v:'mục tiêu chính: kết quả trực tiếp được hỏi; cơ chế tác động: cách một giải pháp tạo ra kết quả; lợi ích phụ: kết quả có liên quan nhưng không phải trọng tâm',kw:'Tìm động từ chính trong câu hỏi, xác định kết quả trực tiếp cần đạt và loại các phương án chỉ tạo lợi ích phụ hoặc áp dụng cho đối tượng khác.',core:'Đáp án đúng tạo ra trực tiếp chức năng hoặc kết quả được hỏi. Các phương án khác có thể cùng chủ đề nhưng khác mục tiêu, đối tượng hoặc cơ chế tác động.'}};return m[k]}
function viWrong(q,i){var k=viKind(q);if(k==='ngoai')return'Sai nếu chọn phương án này vì phương án vẫn đáp ứng nguyên tắc chung. Câu hỏi yêu cầu ngoại lệ, nên phải chọn phương án không tạo ra kết quả chung của ba lựa chọn còn lại.';if(k==='it')return'Sai nếu chọn phương án này vì phương án vẫn hỗ trợ mục tiêu hoặc đáp ứng một điều kiện quan trọng tốt hơn đáp án cần tìm.';if(k==='trinh')return'Sai vì hành động không nằm ở thời điểm quyết định cần thiết. Hành động có thể hữu ích nhưng thực hiện theo trình tự này sẽ quá muộn hoặc chưa đủ cơ sở.';if(k==='nguong')return'Sai vì giá trị, đơn vị hoặc điều kiện định lượng không khớp yêu cầu. Cùng chủ đề nhưng sai ngưỡng vẫn không được chọn.';if(k==='hoso')return'Sai vì phương án không cung cấp đúng loại bằng chứng cần thiết. Phương án có thể liên quan đến quá trình nhưng không xác minh trực tiếp việc tuân thủ.';return'Sai vì phương án không tạo ra đúng chức năng hoặc kết quả được hỏi. Điểm khác biệt nằm ở mục tiêu, đối tượng áp dụng hoặc cơ chế tác động, nên phương án không đáp ứng đầy đủ yêu cầu.'}
function viCards(q){var h='';for(var i=0;i<q.options.length;i++){if(i===q.answer)continue;h+='<div class="distractor-card"><div><b>Phương án '+String.fromCharCode(65+i)+'</b><small>Bản dịch chi tiết của lựa chọn được lược khỏi phần giải thích để tránh hiển thị nội dung lai ngôn ngữ.</small></div><p>'+escapeHtml(viWrong(q,i))+'</p></div>'}return h}
function analysis(q,vi){var correct=String.fromCharCode(65+q.answer)+'. '+q.options[q.answer],quote=coreEvidence(q);if(vi){var z=viPack(q);return'<div class="analysis-line"><b>1. Từ vựng:</b> '+escapeHtml(z.v)+'</div><div class="analysis-line"><b>2. Cách nhận diện đáp án:</b> '+escapeHtml(z.kw)+'</div><div class="deep-explanation"><b>3. '+title5(q,true)+'</b><p class="correct-answer"><b>Đáp án đúng:</b> Phương án '+String.fromCharCode(65+q.answer)+'</p><p class="translation"><b>Bản chất kỹ thuật:</b> '+escapeHtml(z.core)+'</p><p class="answer-link"><b>Mối liên hệ quyết định:</b> Đối chiếu động từ chính của câu hỏi với kết quả thực tế mà từng phương án tạo ra. Chọn phương án đáp ứng trực tiếp và đầy đủ điều kiện, không chọn lợi ích phụ hoặc nội dung chỉ liên quan gián tiếp.</p></div><div class="deep-explanation distractors"><b>4. Phân tích các lựa chọn còn lại</b>'+viCards(q)+'</div>'}return'<div class="analysis-line"><b>1. Key Vocabulary:</b> '+escapeHtml(q.vocabulary)+'</div><div class="analysis-line"><b>2. Answer Keywords:</b> '+escapeHtml(q.keywords)+'</div><div class="deep-explanation"><b>3. '+title5(q,false)+'</b><p class="correct-answer"><b>Correct answer:</b> '+escapeHtml(correct)+'</p><blockquote>“'+escapeHtml(quote)+'”</blockquote><p class="answer-link"><b>Decisive link:</b> '+escapeHtml(bridge(q,false))+'</p></div>'}
/* ENHANCED_BILINGUAL_EXPLANATION_V7_5_15 */
function explList(text){return String(text||'').split(/\s*;\s*/).filter(Boolean).map(function(x){return '<li>'+escapeHtml(x)+'</li>'}).join('')}
function enhancedWrongCards(q,vi){var opts=vi&&(q.options_vi||[]).length===4?q.options_vi:q.options;var reasons=vi?(q.wrong_reasons_vi||[]):(q.wrong_reasons_en||[]);var out='';for(var i=0;i<4;i++){if(i===q.answer)continue;out+='<div class="wrong-card"><b>'+String.fromCharCode(65+i)+'. '+escapeHtml(opts[i])+'</b><div>'+(reasons[i]?escapeHtml(reasons[i]):(vi?'Sai vì phương án này không đáp ứng điều kiện quyết định của câu hỏi.':'Incorrect because this option does not satisfy the decisive condition in the question.'))+'</div></div>'}return out}
analysis=function(q,vi){var opts=vi&&(q.options_vi||[]).length===4?q.options_vi:q.options;var correct=String.fromCharCode(65+q.answer)+'. '+opts[q.answer];if(vi){return '<div class="deep-explanation"><b>Câu hỏi gốc / Original question</b><p>'+escapeHtml(q.q)+'</p><p class="correct-answer"><b>Đáp án đúng:</b> '+escapeHtml(correct)+'</p></div><div class="analysis-line"><b>1. Mục đích câu hỏi</b><p>'+escapeHtml(q.purpose_vi)+'</p></div><div class="analysis-line"><b>2. Từ vựng đáng lưu ý</b><ul>'+explList(q.vocabulary_vi)+'</ul></div><div class="analysis-line"><b>3. Keyword chọn đáp án</b><p>'+escapeHtml(q.keywords_vi)+'</p></div><div class="deep-explanation"><b>4. Khái niệm cốt lõi / Core Concept</b><p>'+escapeHtml(q.core_concept_vi||q.logic_vi||'')+'</p></div>'}return '<div class="deep-explanation"><b>Original question</b><p>'+escapeHtml(q.q)+'</p><p class="correct-answer"><b>Correct answer:</b> '+escapeHtml(correct)+'</p></div><div class="analysis-line"><b>1. Question Purpose</b><p>'+escapeHtml(q.purpose)+'</p></div><div class="analysis-line"><b>2. Key Vocabulary</b><ul>'+explList(q.vocabulary)+'</ul></div><div class="analysis-line"><b>3. Answer Keywords</b><p>'+escapeHtml(q.keywords)+'</p></div><div class="deep-explanation"><b>4. Core Concept</b><p>'+escapeHtml(q.core_concept||q.logic||'')+'</p></div>'}

/* ENGLISH_EXPLANATION_ONLY_V7_5_19 */
function englishVocabList(text){return String(text||'').split(/\s*;\s*/).filter(Boolean).map(function(x){return '<li>'+escapeHtml(x)+'</li>'}).join('')}
var analysisVI=analysis;/* VI_EXPLANATION_RESTORED_V8 */analysis=function(q,vi){if(vi)return analysisVI(q,true);var correct=String.fromCharCode(65+q.answer)+'. '+q.options[q.answer];return '<div class="deep-explanation"><b>Original question</b><p>'+escapeHtml(q.q)+'</p><p class="correct-answer"><b>Correct answer:</b> '+escapeHtml(correct)+'</p></div><div class="analysis-line"><b>1. Question Purpose</b><p>'+escapeHtml(q.purpose)+'</p></div><div class="analysis-line"><b>2. Key Vocabulary</b><ul>'+englishVocabList(q.vocabulary)+'</ul></div><div class="analysis-line"><b>3. Answer Keywords</b><p>'+escapeHtml(q.keywords)+'</p></div><div class="deep-explanation"><b>4. Core Concept</b><p>'+escapeHtml(q.core_concept||'')+'</p></div>'}
/* VI_ALIGNED_4_SECTION_RENDERER_V7_5_23 */
function viVocabList(text){return String(text||'').split(/\s*;\s*/).filter(Boolean).map(function(x){return '<li>'+escapeHtml(x.replace(/^\-\s*/,''))+'</li>'}).join('')}
function analysisVietnamese(q){var letter=String.fromCharCode(65+q.answer),answerEn=q.options[q.answer],answerVi=(q.options_vi&&q.options_vi[q.answer])?q.options_vi[q.answer]:'';return '<div class="deep-explanation"><b>Câu hỏi gốc</b><p>'+escapeHtml(q.q)+'</p><p class="correct-answer"><b>Đáp án đúng:</b> '+letter+'. '+escapeHtml(answerEn)+'</p>'+(answerVi?'<p class="translation"><b>Bản dịch đáp án:</b> '+escapeHtml(answerVi)+'</p>':'')+'</div><div class="analysis-line"><b>1. Mục đích câu hỏi</b><p>'+escapeHtml(q.purpose_vi||'')+'</p></div><div class="analysis-line"><b>2. Từ vựng đáng lưu ý</b><ul>'+viVocabList(q.vocabulary_vi||'')+'</ul></div><div class="analysis-line"><b>3. Keyword chọn đáp án</b><p>'+escapeHtml(q.keywords_vi||'')+'</p></div><div class="deep-explanation"><b>4. Khái niệm cốt lõi</b><p>'+escapeHtml(q.core_concept_vi||'')+'</p></div>'}
function renderExplanation(q){var ok=session.answers[session.index]===q.answer,b=el('explanation');b.style.display='block';b.className=ok?'explain':'explain incorrect';el('answer-status').innerHTML='<b>'+(ok?'CORRECT':'INCORRECT')+'</b> · <b>Correct answer:</b> '+String.fromCharCode(65+q.answer)+'. '+escapeHtml(q.options[q.answer]);el('ex-en').innerHTML=analysis(q,false)}function renderPalette(){var h='',i,cl,n=0;for(i=0;i<100;i++){cl='qbtn';if(session.answers[i]!==null){cl+=' answered';n++;if(paletteMode==='unanswered')cl+=' filtered'}if(session.flags[i])cl+=' flagged';if(i===session.index)cl+=' current';h+='<button class="'+cl+'" onclick="LEED_APP.jump('+i+')">'+(i+1)+'</button>'}el('palette').innerHTML=h;el('progress-label').innerHTML=n+'/100 câu · '+n+'%';el('progress-fill').style.width=n+'%'}
function nextEmpty(){var i;for(i=session.index+1;i<100;i++)if(session.answers[i]===null){jump(i);return}for(i=0;i<=session.index;i++)if(session.answers[i]===null){jump(i);return}alert('Đã trả lời đủ 100 câu.')}
function confirmSubmit(){var n=0,i;for(i=0;i<100;i++)if(session.answers[i]!==null)n++;if(confirm('Đã trả lời '+n+'/100 câu. Còn '+(100-n)+' câu trống. Nộp bài ngay?'))submit()}
function calculate(){var i,q,c=0,w=0,b=0,d={},cat;for(i=0;i<CATEGORY_ORDER.length;i++)d[CATEGORY_ORDER[i]]={total:0,correct:0,wrong:0,blank:0};for(i=0;i<100;i++){q=active[i];cat=q.category;if(!d[cat])d[cat]={total:0,correct:0,wrong:0,blank:0};d[cat].total++;if(session.answers[i]===null){b++;d[cat].blank++}else if(session.answers[i]===q.answer){c++;d[cat].correct++}else{w++;d[cat].wrong++}}return{correct:c,wrong:w,blank:b,answered:100-b,pct:c,fail:100-c,passed:c>=C.passMark,domains:d}}
function saveAttempt(){var h=read(historyKey(),[]),i,count=0,now=(new Date()).getTime();for(i=0;i<h.length;i++)if(h[i].test===session.test&&h[i].mode===session.mode)count++;h.unshift({id:now,test:session.test,mode:session.mode,strategy:session.strategy,attempt:count+1,date:now,elapsed:session.mode==='exam'?C.examSeconds-session.remaining:Math.round((now-session.startedAt)/1000),correct:result.correct,wrong:result.wrong,blank:result.blank,pct:result.pct,passed:result.passed,map:session.map,orders:session.orders,answers:session.answers,flags:session.flags,checked:session.checked});if(h.length>200)h=h.slice(0,200);write(historyKey(),h)}
function showResultScreen(){screen('results');el('score').innerHTML=result.pct+'%';el('donut-path').setAttribute('stroke-dasharray',result.pct+',100');el('pass-status').innerHTML=result.passed?'ĐẠT / PASS':'CHƯA ĐẠT / FAIL';el('pass-status').style.color=result.passed?'#10b981':'#ef4444';el('result-detail').innerHTML=(session.mode==='exam'?'Exam Mode':'Practice Mode')+' · Đúng '+result.correct+' · Sai '+result.wrong+' · Trống '+result.blank;el('stats').innerHTML='<div class="stat"><strong>'+result.pct+'%</strong>Correct</div><div class="stat"><strong>'+result.fail+'%</strong>Incorrect/Blank</div><div class="stat"><strong>'+result.answered+'/100</strong>Answered</div>';renderDomains();prepareReview();renderReview()}
function submit(){if(timer){clearInterval(timer);timer=null}result=calculate();session.submitted=true;saveAttempt();try{if(window.LEED_SYNC&&window.LEED_SYNC.markDeleted)window.LEED_SYNC.markDeleted(progressKey(session.test,session.mode));else localStorage.removeItem(progressKey(session.test,session.mode))}catch(e){}showResultScreen()}
function openHistoryAttempt(id){var h=read(historyKey(),[]),x=null,i;for(i=0;i<h.length;i++)if(String(h[i].id||h[i].date)===String(id)){x=h[i];break}if(!x||!x.map||!x.orders||!x.answers){alert('Lần làm bài này được lưu ở phiên bản cũ nên chưa có dữ liệu chi tiết để xem lại.');return}session={test:x.test,mode:x.mode,strategy:x.strategy||'history',index:0,answers:x.answers.slice(0),flags:(x.flags||[]).slice(0),checked:(x.checked||[]).slice(0),remaining:0,startedAt:x.date,submitted:true,autoAdvance:false,map:x.map,orders:x.orders};while(session.answers.length<100)session.answers.push(null);while(session.flags.length<100)session.flags.push(false);while(session.checked.length<100)session.checked.push(true);buildActive();result=calculate();showResultScreen()}
function renderDomains(){var i,k,x,pc,pw,pb,h='<div class="domain-legend"><span><i class="legend-dot correct"></i>Chính xác</span><span><i class="legend-dot wrong"></i>Không đúng</span><span><i class="legend-dot blank"></i>Đã bỏ qua/Chưa có đáp án</span></div>';for(i=0;i<CATEGORY_ORDER.length;i++){k=CATEGORY_ORDER[i];x=result.domains[k]||{total:0,correct:0,wrong:0,blank:0};pc=x.total?Math.round(x.correct*100/x.total):0;pw=x.total?Math.round(x.wrong*100/x.total):0;pb=x.total?Math.max(0,100-pc-pw):100;h+='<div class="domain"><div class="domain-head"><span>'+escapeHtml(k)+' ('+x.total+' câu hỏi)</span><span>'+pc+'% đúng</span></div><div class="domain-stacked">'+(pc?'<div class="seg correct" style="width:'+pc+'%">'+pc+'%</div>':'')+(pw?'<div class="seg wrong" style="width:'+pw+'%">'+pw+'%</div>':'')+(pb?'<div class="seg blank" style="width:'+pb+'%">'+pb+'%</div>':'')+'</div></div>'}el('domains').innerHTML=h}
function prepareReview(){var k,h='<option value="all">Tất cả các lĩnh vực</option>',flag=0,i;for(i=0;i<CATEGORY_ORDER.length;i++){k=CATEGORY_ORDER[i];h+='<option value="'+escapeHtml(k)+'">'+escapeHtml(k)+'</option>'};el('review-domain').innerHTML=h;reviewMode='all';reviewDomain='all';for(i=0;i<100;i++)if(session.flags[i])flag++;el('review-all').innerHTML='100 tất cả';el('review-correct').innerHTML=result.correct+' chính xác';el('review-wrong').innerHTML=result.wrong+' không chính xác';el('review-blank').innerHTML=result.blank+' bỏ qua';el('review-flagged').innerHTML=flag+' đánh dấu';updatePills()}
function updatePills(){var ids=['review-all','review-correct','review-wrong','review-blank','review-flagged'],vals=['all','correct','wrong','blank','flagged'],i;for(i=0;i<ids.length;i++)el(ids[i]).className='filter-pill'+(reviewMode===vals[i]?' active':'')}
function setReview(m){reviewMode=m;updatePills();renderReview()}
function renderReview(){var h='',i,j,q,a,ok,status,sc,oc,badge;for(i=0;i<100;i++){q=active[i];a=session.answers[i];ok=a===q.answer;if(reviewDomain!=='all'&&q.category!==reviewDomain)continue;if(reviewMode==='correct'&&!ok)continue;if(reviewMode==='wrong'&&(ok||a===null))continue;if(reviewMode==='blank'&&a!==null)continue;if(reviewMode==='flagged'&&!session.flags[i])continue;status=a===null?'Đã bỏ qua':(ok?'Chính xác':'Không chính xác');sc=a===null?'blank':(ok?'correct':'incorrect');h+='<div id="review-card-'+i+'" class="review-card"><div class="review-head" onclick="LEED_APP.toggleCard('+i+')"><span class="review-status-icon '+sc+'">'+(a===null?'–':(ok?'✓':'×'))+'</span><div class="review-title">Câu '+(i+1)+' · '+status+'</div><span class="review-chevron">⌃</span></div><div class="review-body"><div class="review-question">'+escapeHtml(q.q)+'</div><div class="review-options">';for(j=0;j<4;j++){oc='review-option';badge='';if(j===q.answer){oc+=' correct-choice';badge='<span class="answer-badge">Đáp án đúng</span>'}if(a===j&&j!==q.answer){oc+=' wrong-choice';badge='<span class="answer-badge wrong-badge">Bạn đã chọn</span>'}h+='<div class="'+oc+'"><span class="review-radio">'+((a===j||j===q.answer)?'✓':'')+'</span><div>'+badge+'<div>'+String.fromCharCode(65+j)+'. '+escapeHtml(q.options[j])+'</div>'+((q.options_vi||[]).length===4&&q.options_vi[j]!==q.options[j]?'<small class="option-translation">'+escapeHtml(q.options_vi[j])+'</small>':'')+'</div></div>'}h+='</div><div class="review-explanation"><h4>English Explanation</h4>'+analysis(q,false)+'</div></div></div>'}el('review').innerHTML=h||'<div class="review-empty">Không có câu phù hợp.</div>';collapsed=false;el('collapse-all').innerHTML='Thu gọn tất cả câu hỏi'}
function toggleCard(i){var c=el('review-card-'+i);if(c)c.className=c.className.indexOf('collapsed')>=0?c.className.replace(' collapsed',''):c.className+' collapsed'}
function toggleCollapse(){var cards=el('review').getElementsByClassName('review-card'),i;collapsed=!collapsed;for(i=0;i<cards.length;i++){if(collapsed&&cards[i].className.indexOf('collapsed')<0)cards[i].className+=' collapsed';if(!collapsed)cards[i].className=cards[i].className.replace(' collapsed','')}el('collapse-all').innerHTML=collapsed?'Mở rộng tất cả':'Thu gọn tất cả câu hỏi'}
function prepareHistoryFilter(){var h='<option value="all">Tất cả bài test</option><option value="-1">Auto Mix</option>',i,v=el('history-test-filter').value||'all';for(i=0;i<C.testCount;i++)h+='<option value="'+i+'">Test '+(i+1)+'</option>';el('history-test-filter').innerHTML=h;el('history-test-filter').value=v}
function renderSummary(){var h=read(historyKey(),[]),e=0,p=0,be=null,bp=null,i;for(i=0;i<h.length;i++){if(h[i].mode==='exam'){e++;if(be===null||h[i].pct>be)be=h[i].pct}else{p++;if(bp===null||h[i].pct>bp)bp=h[i].pct}}el('attempt-summary').innerHTML='<div class="attempt-summary-card"><strong>'+e+'</strong>Lần Exam</div><div class="attempt-summary-card"><strong>'+p+'</strong>Lần Practice</div><div class="attempt-summary-card"><strong>'+(be===null?'–':be+'%')+'</strong>Exam cao nhất</div><div class="attempt-summary-card"><strong>'+(bp===null?'–':bp+'%')+'</strong>Practice cao nhất</div>'}
function historyItemKey(x){return String(x.id||x.date)}
function visibleHistoryKeys(){var h=read(historyKey(),[]),tf=el('history-test-filter').value,mf=el('history-mode-filter').value,out=[],i,x;for(i=0;i<h.length;i++){x=h[i];if(tf!=='all'&&String(x.test)!==tf)continue;if(mf!=='all'&&x.mode!==mf)continue;out.push(historyItemKey(x))}return out}
function updateHistorySelection(){var boxes=document.querySelectorAll('.history-check'),checked=document.querySelectorAll('.history-check:checked'),all=el('history-select-all'),del=el('delete-selected-history-btn');if(all){all.checked=boxes.length>0&&checked.length===boxes.length;all.indeterminate=checked.length>0&&checked.length<boxes.length}if(del){del.disabled=checked.length===0;del.textContent=checked.length?'Xóa mục đã chọn ('+checked.length+')':'Xóa mục đã chọn'}}
function toggleSelectAllHistory(){var boxes=document.querySelectorAll('.history-check'),v=this.checked,i;for(i=0;i<boxes.length;i++)boxes[i].checked=v;updateHistorySelection();updateHistoryCollapseButton()}
var historyGroupOpen={};
function historyGroupKey(x){return String(x.test)+'|'+String(x.mode||'exam')}
function historyGroupLabel(x){return (x.test===-1?'Auto Mix':'Test '+(Number(x.test)+1))+' · '+String(x.mode||'exam')}
function toggleHistoryGroup(key){historyGroupOpen[key]=!historyGroupOpen[key];renderHistory()}
function filteredHistoryGroupKeys(){var h=read(historyKey(),[]),tf=el('history-test-filter').value,mf=el('history-mode-filter').value,seen={},keys=[],i,x,k;for(i=0;i<h.length;i++){x=h[i];if(tf!=='all'&&String(x.test)!==tf)continue;if(mf!=='all'&&x.mode!==mf)continue;k=historyGroupKey(x);if(!seen[k]){seen[k]=1;keys.push(k)}}return keys}
function updateHistoryCollapseButton(){var b=el('history-collapse-all-btn'),keys=filteredHistoryGroupKeys(),allClosed=keys.length>0&&keys.every(function(k){return historyGroupOpen[k]===false});if(b){b.disabled=keys.length===0;b.textContent=allClosed?'Mở rộng tất cả':'Thu gọn tất cả';b.setAttribute('aria-expanded',String(!allClosed))}}
function toggleAllHistoryGroups(){var keys=filteredHistoryGroupKeys(),allClosed=keys.length>0&&keys.every(function(k){return historyGroupOpen[k]===false}),i;for(i=0;i<keys.length;i++)historyGroupOpen[keys[i]]=allClosed;renderHistory()}
function renderHistoryRow(x){var d=new Date(x.date),canReview=!!(x.map&&x.orders&&x.answers),key=historyItemKey(x),elapsed=(typeof x.elapsed==='number')?timeText(Math.max(0,Math.round(x.elapsed))):(typeof x.timeUsed==='number'?timeText(Math.max(0,Math.round(x.timeUsed))):'--:--:--');return '<div class="history-item'+(canReview?' history-reviewable':'')+'"><div class="history-check-cell"><input class="history-check" type="checkbox" value="'+escapeHtml(key)+'" onchange="LEED_APP.historySelectionChanged()" aria-label="Chọn lần làm bài '+escapeHtml(String(x.attempt||''))+'"></div><div><b>Lần '+escapeHtml(String(x.attempt||''))+'</b><br><span class="history-mode">'+escapeHtml(x.mode)+'</span></div><div><div class="history-date">'+pad(d.getDate())+'/'+pad(d.getMonth()+1)+'/'+d.getFullYear()+'</div><div class="history-date">Thời gian: '+elapsed+'</div></div><div class="history-score">'+x.pct+'%</div><div class="'+(x.passed?'history-pass':'history-fail')+'">'+(x.passed?'PASS':'FAIL')+'</div><div>Đúng '+x.correct+'</div><div>Sai '+x.wrong+'</div><div>Trống '+x.blank+'</div><div class="history-actions">'+(canReview?'<button type="button" class="history-review-btn" onclick="LEED_APP.openHistory(\''+escapeHtml(key)+'\')">Xem lại</button>':'<span class="history-unavailable">Bản cũ</span>')+'<button type="button" class="history-delete-btn" onclick="LEED_APP.deleteHistory(\''+escapeHtml(key)+'\')">Xóa lần này</button></div></div>'}
function renderHistory(){var h=read(historyKey(),[]),tf=el('history-test-filter').value,mf=el('history-mode-filter').value,groups={},order=[],out='',i,x,gk,g,open;for(i=0;i<h.length;i++){x=h[i];if(tf!=='all'&&String(x.test)!==tf)continue;if(mf!=='all'&&x.mode!==mf)continue;gk=historyGroupKey(x);if(!groups[gk]){groups[gk]=[];order.push(gk)}groups[gk].push(x)}for(i=0;i<order.length;i++){gk=order[i];g=groups[gk];g.sort(function(a,b){return Number(b.date||0)-Number(a.date||0)});open=historyGroupOpen[gk]!==false;out+='<section class="history-group"><button type="button" class="history-group-toggle" onclick="LEED_APP.toggleHistoryGroup(\''+escapeHtml(gk)+'\')" aria-expanded="'+open+'"><span class="history-group-arrow">'+(open?'▼':'▶')+'</span><span class="history-group-name">'+escapeHtml(historyGroupLabel(g[0]))+'</span><span class="history-group-count">'+g.length+' lần</span></button><div class="history-group-items'+(open?'':' hidden')+'">';for(var j=0;j<g.length;j++)out+=renderHistoryRow(g[j]);out+='</div></section>'}el('history-list').innerHTML=out||'<div class="history-empty">Chưa có lịch sử.</div>';el('history-select-all').checked=false;el('history-select-all').indeterminate=false;updateHistorySelection()}

async function deleteHistoryItem(key){if(!confirm('Xóa mục lịch sử này?'))return;try{if(window.LEED_SYNC&&window.LEED_SYNC.markHistoryDeleted)await window.LEED_SYNC.markHistoryDeleted([String(key)]);else{var h=read(historyKey(),[]),next=h.filter(function(x){return historyItemKey(x)!==String(key)});write(historyKey(),next)}}catch(e){console.error(e);alert('Không thể xóa mục lịch sử. Vui lòng thử lại.');return}renderSummary();renderHistory()}
async function deleteSelectedHistory(){var boxes=document.querySelectorAll('.history-check:checked'),keys=[],i;if(!boxes.length)return;for(i=0;i<boxes.length;i++)keys.push(String(boxes[i].value));if(!confirm('Xóa '+keys.length+' mục lịch sử đã chọn?'))return;try{if(window.LEED_SYNC&&window.LEED_SYNC.markHistoryDeleted)await window.LEED_SYNC.markHistoryDeleted(keys);else{var h=read(historyKey(),[]),next=h.filter(function(x){return keys.indexOf(historyItemKey(x))<0});write(historyKey(),next)}}catch(e){console.error(e);alert('Không thể xóa các mục lịch sử. Vui lòng thử lại.');return}renderSummary();renderHistory()}

async function clearHistory(){if(confirm('Xóa toàn bộ lịch sử?')){try{if(window.LEED_SYNC&&window.LEED_SYNC.markDeleted)await window.LEED_SYNC.markDeleted(historyKey());else localStorage.removeItem(historyKey())}catch(e){console.error(e)}renderSummary();renderHistory()}}
function goMenu(){if(timer){clearInterval(timer);timer=null}saveProgress();renderMenu()} async function discard(t,m){if(confirm('Xóa tiến trình này?')){try{if(window.LEED_SYNC&&window.LEED_SYNC.markDeleted)await window.LEED_SYNC.markDeleted(progressKey(t,m));else localStorage.removeItem(progressKey(t,m))}catch(e){console.error(e)}renderMenu()}}
function init(){try{validateData();bind();renderMenu()}catch(e){document.body.innerHTML='<div class="container"><div class="panel"><h2>Lỗi khởi động</h2><p>'+escapeHtml(e.message)+'</p><p>Hãy giải nén lại toàn bộ gói mới.</p></div></div>'}}
window.LEED_APP={start:start,discard:discard,answer:answer,jump:jump,toggleCard:toggleCard,openHistory:openHistoryAttempt,deleteHistory:deleteHistoryItem,historySelectionChanged:updateHistorySelection,toggleHistoryGroup:toggleHistoryGroup,toggleAllHistoryGroups:toggleAllHistoryGroups,refreshMenu:function(){var m=el('menu'),x=el('exam'),r=el('results');if(m&&m.className.indexOf('hidden')<0&&x&&x.className.indexOf('hidden')>=0&&r&&r.className.indexOf('hidden')>=0)renderMenu()}};
init();
})();
